using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace ContainerOrchestrator.Services
{
    public class ContainerMetadata
    {
        public string ContainerId { get; set; }
        public string ImageName { get; set; }
        public string Namespace { get; set; }
        public Dictionary<string, string> Labels { get; set; }
    }

    public interface IQueryFilterBuilder
    {
        string BuildFilterClause(Dictionary<string, string> filters);
    }

    public class SafeQueryFilterBuilder : IQueryFilterBuilder
    {
        private static readonly HashSet<string> AllowedColumns = new HashSet<string>(
            new[] { "container_id", "image_name", "namespace", "status", "node_id" },
            StringComparer.OrdinalIgnoreCase);

        public string BuildFilterClause(Dictionary<string, string> filters)
        {
            if (filters == null || filters.Count == 0)
                return "1=1";

            var clauses = new List<string>();
            foreach (var kvp in filters)
            {
                if (!AllowedColumns.Contains(kvp.Key))
                    throw new ArgumentException($"Invalid filter column: {kvp.Key}");
                clauses.Add($"{kvp.Key} = @{kvp.Key}");
            }
            return string.Join(" AND ", clauses);
        }
    }

    public class LabelQueryFilterBuilder : IQueryFilterBuilder
    {
        public string BuildFilterClause(Dictionary<string, string> filters)
        {
            if (filters == null || filters.Count == 0)
                return "1=1";

            var clauses = new List<string>();
            foreach (var kvp in filters)
            {
                // Labels use a JSON path query - column is fixed, only value is dynamic
                var sanitizedKey = kvp.Key.Replace("'", "''").Replace("\\", "\\\\");
                var sanitizedValue = kvp.Value.Replace("'", "''").Replace("\\", "\\\\");
                clauses.Add($"JSON_VALUE(labels, '$.{sanitizedKey}') = '{sanitizedValue}'");
            }
            return string.Join(" AND ", clauses);
        }
    }

    public class ContainerQueryContext
    {
        public Dictionary<string, string> ColumnFilters { get; set; }
        public Dictionary<string, string> LabelFilters { get; set; }
        public string OrderBy { get; set; }
        public int Limit { get; set; } = 100;
    }

    public class ContainerRegistryService
    {
        private readonly string _connectionString;
        private readonly IQueryFilterBuilder _columnFilterBuilder;
        private readonly IQueryFilterBuilder _labelFilterBuilder;
        private readonly SemaphoreSlim _querySemaphore = new SemaphoreSlim(10, 10);

        public ContainerRegistryService(string connectionString)
        {
            _connectionString = connectionString;
            _columnFilterBuilder = new SafeQueryFilterBuilder();
            _labelFilterBuilder = new LabelQueryFilterBuilder();
        }

        public async Task<List<ContainerMetadata>> QueryContainersAsync(
            ContainerQueryContext context, CancellationToken ct = default)
        {
            await _querySemaphore.WaitAsync(ct);
            try
            {
                var columnFilter = _columnFilterBuilder.BuildFilterClause(context.ColumnFilters);
                var labelFilter = _labelFilterBuilder.BuildFilterClause(context.LabelFilters);

                var orderClause = BuildOrderClause(context.OrderBy);
                var query = BuildFinalQuery(columnFilter, labelFilter, orderClause, context.Limit);

                return await ExecuteQueryAsync(query, context.ColumnFilters, ct);
            }
            finally
            {
                _querySemaphore.Release();
            }
        }

        private string BuildOrderClause(string orderBy)
        {
            var allowed = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                { "container_id", "image_name", "created_at", "namespace" };

            if (string.IsNullOrEmpty(orderBy) || !allowed.Contains(orderBy))
                return "created_at DESC";

            return $"{orderBy} ASC";
        }

        private string BuildFinalQuery(string columnFilter, string labelFilter,
            string orderClause, int limit)
        {
            return $@"SELECT TOP({limit}) container_id, image_name, namespace, labels
                      FROM container_registry
                      WHERE ({columnFilter}) AND ({labelFilter})
                      ORDER BY {orderClause}";
        }

        private async Task<List<ContainerMetadata>> ExecuteQueryAsync(
            string query, Dictionary<string, string> parameters, CancellationToken ct)
        {
            var results = new List<ContainerMetadata>();

            using (var conn = new SqlConnection(_connectionString))
            {
                await conn.OpenAsync(ct);
                using (var cmd = new SqlCommand(query, conn))
                {
                    cmd.CommandTimeout = 30;
                    if (parameters != null)
                    {
                        foreach (var p in parameters)
                            cmd.Parameters.AddWithValue($"@{p.Key}", p.Value);
                    }

                    using (var reader = await cmd.ExecuteReaderAsync(ct))
                    {
                        while (await reader.ReadAsync(ct))
                        {
                            results.Add(new ContainerMetadata
                            {
                                ContainerId = reader.GetString(0),
                                ImageName = reader.GetString(1),
                                Namespace = reader.GetString(2)
                            });
                        }
                    }
                }
            }
            return results;
        }

        public async Task<List<ContainerMetadata>> BatchQueryAsync(
            IEnumerable<ContainerQueryContext> contexts, CancellationToken ct = default)
        {
            var tasks = contexts.Select(ctx => QueryContainersAsync(ctx, ct));
            var results = await Task.WhenAll(tasks);
            return results.SelectMany(r => r).ToList();
        }
    }
}
